import pandas as pdinput_file = "output/reconciliation_detail.csv"df = pd.read_csv(input_file)# KPI Summarykpi = pd.DataFrame({    "total_trades": [len(df)],    "matched": [(df["recon_status"] == "MATCHED").sum()],    "warnings": [(df["recon_status"] == "TOLERANCE_WARNING").sum()],    "breaks": [(df["recon_status"] == "PRICE_BREAK").sum()],    "missing": [(df["recon_status"] == "MARKET_DATA_MISSING").sum()]})kpi["match_rate"] = (kpi["matched"] / kpi["total_trades"]) * 100kpi.to_csv("output/kpi_summary.csv", index=False)# Status Summarystatus_summary = df["recon_status"].value_counts().reset_index()status_summary.columns = ["status", "count"]status_summary.to_csv("output/status_summary.csv", index=False)# Severity Summaryseverity_summary = df["severity"].value_counts().reset_index()severity_summary.columns = ["severity", "count"]severity_summary.to_csv("output/severity_summary.csv", index=False)# Symbol Breakdownsymbol_breaks = df[df["recon_status"] == "PRICE_BREAK"] \    .groupby("symbol") \    .size() \    .reset_index(name="break_count") \    .sort_values(by="break_count", ascending=False)symbol_breaks.to_csv("output/symbol_breaks.csv", index=False)print("✅ Tableau files generated successfully")